window.__finlexDocLoaded(165,{"id":165,"articles":[{"id":4130,"no":"第一条","heading":"","text":"为了规范注册会计师在财务报表审计中与舞弊相关的责任，制定本准则。","seq":0,"links":[{"doc_id":140,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":141,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":144,"tier":"L3","score":64,"rel_kind":"cites","target_seq":1,"target_art_no":"第2项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":144,"tier":"L3","score":64,"rel_kind":"cites","target_seq":6,"target_art_no":"第7项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":171,"tier":"L3","score":64,"rel_kind":"cites","target_seq":1,"target_art_no":"第二条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":178,"tier":"L3","score":64,"rel_kind":"cites","target_seq":3,"target_art_no":"第四条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":182,"tier":"L3","score":64,"rel_kind":"cites","target_seq":1,"target_art_no":"第二条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":182,"tier":"L3","score":64,"rel_kind":"cites","target_seq":5,"target_art_no":"第六条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":182,"tier":"L3","score":64,"rel_kind":"cites","target_seq":11,"target_art_no":"第十二条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":182,"tier":"L3","score":64,"rel_kind":"cites","target_seq":12,"target_art_no":"第十三条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"},{"doc_id":182,"tier":"L3","score":64,"rel_kind":"cites","target_seq":19,"target_art_no":"第二十条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》"}]},{"id":4131,"no":"第二条","heading":"","text":"在涉及识别、评估和应对舞弊导致的重大错报风险时，本准则是对注册会计师如何应用《中国注册会计师审计准则第1211号——重大错报风险的识别和评估》和《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施》的进一步扩展。","seq":1,"links":[{"doc_id":171,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1211号——重大错报风险的识别和评估（2022年12月22日修订）》"},{"doc_id":173,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施（2022年12月22日修订）》"}]},{"id":4132,"no":"第三条","heading":"","text":"财务报表的错报可能由于舞弊或错误所致。舞弊和错误的区别在于，导致财务报表发生错报的行为是故意行为还是非故意行为。","seq":2},{"id":4133,"no":"第四条","heading":"","text":"舞弊是一个宽泛的法律概念，但注册会计师关注的是导致财务报表发生重大错报的舞弊。与财务报表审计相关的故意错报，包括编制虚假财务报告导致的错报和侵占资产导致的错报。尽管注册会计师可能怀疑被审计单位存在舞弊，甚至在极少数情况下识别出发生的舞弊，但注册会计师并不对舞弊是否已实际发生作出法律意义上的判定。","seq":3},{"id":4134,"no":"第五条","heading":"","text":"被审计单位治理层和管理层对防止或发现舞弊负有主要责任。管理层在治理层的监督下，高度重视对舞弊的防范和遏制是非常重要的。对舞弊进行防范可以减少舞弊发生的机会；对舞弊进行遏制，即发现和惩罚舞弊行为，能够警示被审计单位人员不要实施舞弊。对舞弊的防范和遏制需要管理层营造诚实守信和合乎道德的文化，并且这一文化能够在治理层的有效监督下得到强化。治理层的监督包括考虑管理层凌驾于控制之上或对财务报告过程施加其他不当影响的可能性，例如，管理层为了影响分析师对被审计单位业绩和盈利能力的看法而操纵利润。","seq":4},{"id":4135,"no":"第六条","heading":"","text":"在按照审计准则的规定执行审计工作时，注册会计师有责任对财务报表整体是否不存在舞弊或错误导致的重大错报获取合理保证。由于审计的固有限制，即使注册会计师按照审计准则的规定恰当计划和执行了审计工作，也不可避免地存在财务报表中的某些重大错报未被发现的风险。","seq":5},{"id":4136,"no":"第七条","heading":"","text":"在舞弊导致错报的情况下，固有限制的潜在影响尤其重大。舞弊导致的重大错报未被发现的风险，大于错误导致的重大错报未被发现的风险。其原因是舞弊可能涉及精心策划和蓄意实施以进行隐瞒（如伪造证明或故意漏记交易），或者故意向注册会计师提供虚假陈述。如果涉及串通舞弊，注册会计师可能更加难以发现蓄意隐瞒的企图。串通舞弊可能导致原本虚假的审计证据被注册会计师误认为具有说服力。注册会计师发现舞弊的能力取决于舞弊者实施舞弊的技巧、舞弊者操纵会计记录的频率和范围、舞弊者操纵的每笔金额的大小、舞弊者在被审计单位的职位级别、串通舞弊的程度等因素。即使可以识别出实施舞弊的潜在机会，但对于诸如会计估计等判断领域的错报，注册会计师也难以确定这类错报是舞弊还是错误导致的。","seq":6},{"id":4137,"no":"第八条","heading":"","text":"管理层舞弊导致的重大错报未被发现的风险，大于员工舞弊导致的重大错报未被发现的风险。其原因是管理层往往可以利用职务之便，直接或间接操纵会计记录，提供虚假的财务信息，或凌驾于为防止其他员工实施类似舞弊而建立的控制之上。","seq":7},{"id":4138,"no":"第九条","heading":"","text":"在获取合理保证时，注册会计师有责任在整个审计过程中保持职业怀疑，考虑管理层凌驾于控制之上的可能性，并认识到对发现错误有效的审计程序未必对发现舞弊有效。本准则的规定旨在帮助注册会计师识别和评估舞弊导致的重大错报风险，以及设计用以发现这类错报的审计程序。根据法律法规或相关职业道德要求，对于被审计单位的违反法律法规行为（包括舞弊），注册会计师可能承担额外责任。这些责任可能与本准则和其他审计准则不同，或超出了本准则和其他审计准则的规定，例如： （一）应对识别出的或怀疑存在的违反法律法规行为，包括要求与管理层和治理层专门进行沟通，评价其对违反法律法规行为所作应对的适当性，并确定是否需要采取进一步行动； （二）向其他注册会计师（例如，在集团财务报表审计中）沟通识别出的或怀疑存在的违反法律法规行为； **（三）对识别出的或怀疑存在的违反法律法规行为的记录要求。** 对额外责任的履行，可能提供与注册会计师按照本准则和其他审计准则执行工作相关的进一步信息（如与管理层和治理层诚信相关的信息）。 ## 第二章 定义","seq":8},{"id":4139,"no":"第十条","heading":"","text":"舞弊，是指被审计单位的管理层、治理层、员工或第三方使用欺骗手段获取不当或非法利益的故意行为。","seq":9},{"id":4140,"no":"第十一条","heading":"","text":"舞弊风险因素，是指表明实施舞弊的动机或压力，或者为实施舞弊提供机会的事项或情况。 ## 第三章 目标","seq":10},{"id":4141,"no":"第十二条","heading":"","text":"注册会计师的目标是： **（一）识别和评估舞弊导致的财务报表重大错报风险；** （二）通过设计和实施恰当的应对措施，针对评估的舞弊导致的重大错报风险，获取充分、适当的审计证据； **（三）恰当应对审计过程中识别出的舞弊或舞弊嫌疑。** ## 第四章 要求 ### 第一节 职业怀疑","seq":11},{"id":4142,"no":"第十三条","heading":"","text":"按照《中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求》的规定，注册会计师应当在整个审计过程中保持职业怀疑，认识到存在舞弊导致的重大错报的可能性，而不应受到以前对管理层、治理层正直和诚信形成的判断的影响。","seq":12,"links":[{"doc_id":161,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求（2022年12月22日修订）》"}]},{"id":4143,"no":"第十四条","heading":"","text":"除非存在相反的理由，注册会计师可以将文件和记录作为真品。但如果在审计过程中识别出的情况使注册会计师认为文件可能是伪造的或文件中的某些条款已发生变动但未告知注册会计师，注册会计师应当作出进一步调查。","seq":13},{"id":4144,"no":"第十五条","heading":"","text":"如果管理层或治理层对询问作出的答复相互之间不一致或与其他信息不一致，注册会计师应当对这种不一致加以调查。 ### 第二节 项目组内部的讨论","seq":14},{"id":4145,"no":"第十六条","heading":"","text":"按照《中国注册会计师审计准则第1211号——重大错报风险的识别和评估》的规定，项目组成员之间应当进行讨论，并由项目合伙人确定将哪些事项向未参与讨论的项目组成员通报。项目组内部讨论的重点应当包括财务报表易于发生舞弊导致的重大错报的方式和领域，包括舞弊可能如何发生。在讨论过程中，项目组成员不应假定管理层和治理层是正直和诚信的。 ### 第三节 风险评估程序和相关活动","seq":15,"links":[{"doc_id":171,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1211号——重大错报风险的识别和评估（2022年12月22日修订）》"}]},{"id":4146,"no":"第十七条","heading":"","text":"当按照《中国注册会计师审计准则第1211号——重大错报风险的识别和评估》的规定实施风险评估程序和相关活动，以了解被审计单位及其环境、适用的财务报告编制基础和被审计单位内部控制体系时，注册会计师应当实施本准则第十八条至第二十五条规定的审计程序，以获取用以识别舞弊导致的重大错报风险的信息。","seq":16,"links":[{"doc_id":171,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1211号——重大错报风险的识别和评估（2022年12月22日修订）》"}]},{"id":4147,"no":"第十八条","heading":"","text":"注册会计师应当向管理层询问： （一）管理层对财务报表可能存在舞弊导致的重大错报风险的评估，包括评估的性质、范围和频率等； （二）管理层对舞弊风险的识别和应对过程，包括管理层识别出的或注意到的特定舞弊风险，或可能存在舞弊风险的各类交易、账户余额或披露； **（三）管理层就其对舞弊风险的识别和应对过程向治理层的通报；** **（四）管理层就其经营理念和道德观念向员工的通报。**","seq":17},{"id":4148,"no":"第十九条","heading":"","text":"注册会计师应当询问管理层和被审计单位内部的其他人员（如适用），以确定其是否知悉任何影响被审计单位的舞弊事实、舞弊嫌疑或舞弊指控。","seq":18},{"id":4149,"no":"第二十条","heading":"","text":"如果被审计单位设有内部审计，注册会计师应当询问内部审计人员，以确定其是否知悉任何影响被审计单位的舞弊事实、舞弊嫌疑或舞弊指控，并获取这些人员对舞弊风险的看法。","seq":19},{"id":4150,"no":"第二十一条","heading":"","text":"除非治理层全部成员参与管理被审计单位，注册会计师应当了解治理层如何监督管理层对舞弊风险的识别和应对过程，以及为降低舞弊风险而建立的控制。","seq":20},{"id":4151,"no":"第二十二条","heading":"","text":"除非治理层全部成员参与管理被审计单位，注册会计师应当询问治理层，以确定其是否知悉任何影响被审计单位的舞弊事实、舞弊嫌疑或舞弊指控。治理层对这些询问的答复，还可在一定程度上作为管理层答复的佐证信息。","seq":21,"links":[{"doc_id":167,"tier":"L3","score":72,"rel_kind":"cites","target_seq":23,"target_art_no":"第二十四条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》第22条"}]},{"id":4152,"no":"第二十三条","heading":"","text":"注册会计师应当评价在实施分析程序时识别出的异常或偏离预期的关系（包括与收入账户有关的关系），是否表明存在舞弊导致的重大错报风险。","seq":22},{"id":4153,"no":"第二十四条","heading":"","text":"注册会计师应当考虑获取的其他信息是否表明存在舞弊导致的重大错报风险。","seq":23},{"id":4154,"no":"第二十五条","heading":"","text":"注册会计师应当评价通过其他风险评估程序和相关活动获取的信息，是否表明存在舞弊风险因素。存在舞弊风险因素并不必然表明发生了舞弊，但在舞弊发生时通常存在舞弊风险因素，因此，舞弊风险因素可能表明存在舞弊导致的重大错报风险。 ### 第四节 识别和评估舞弊导致的重大错报风险","seq":24},{"id":4155,"no":"第二十六条","heading":"","text":"按照《中国注册会计师审计准则第1211号——重大错报风险的识别和评估》的规定，注册会计师应当在财务报表层次和各类交易、账户余额、披露的认定层次识别和评估舞弊导致的重大错报风险。","seq":25,"links":[{"doc_id":171,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1211号——重大错报风险的识别和评估（2022年12月22日修订）》"}]},{"id":4156,"no":"第二十七条","heading":"","text":"在识别和评估舞弊导致的重大错报风险时，注册会计师应当基于收入确认存在舞弊风险的假定，评价哪些类型的收入、收入交易或认定将导致舞弊风险。如果认为收入确认存在舞弊风险的假定不适用于业务的具体情况，从而未将收入确认作为舞弊导致的重大错报风险领域，注册会计师应当按照本准则第五十一条的规定形成相应的审计工作底稿。","seq":26},{"id":4157,"no":"第二十八条","heading":"","text":"注册会计师应当将评估的舞弊导致的重大错报风险作为特别风险。如果此前未识别与此类风险相关的控制，注册会计师应当识别被审计单位用于应对该特别风险的控制，评价控制的设计，并确定控制是否得到执行。 ### 第五节 应对评估的舞弊导致的重大错报风险","seq":27},{"id":4158,"no":"第二十九条","heading":"","text":"按照《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施》的规定，注册会计师应当针对评估的舞弊导致的财务报表层次重大错报风险确定总体应对措施。","seq":28,"links":[{"doc_id":173,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施（2022年12月22日修订）》"}]},{"id":4159,"no":"第三十条","heading":"","text":"在针对评估的舞弊导致的财务报表层次重大错报风险确定总体应对措施时，注册会计师应当： （一）在分派和督导项目组成员时，考虑承担重要业务职责的项目组成员所具备的知识、技能和能力，并考虑舞弊导致的重大错报风险的评估结果； （二）评价被审计单位对会计政策（特别是涉及主观计量和复杂交易的会计政策）的选择和运用，是否可能表明管理层通过操纵利润对财务信息作出虚假报告； （三）在选择审计程序的性质、时间安排和范围时，增加审计程序的不可预见性。","seq":29},{"id":4160,"no":"第三十一条","heading":"","text":"按照《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施》的规定，注册会计师应当设计和实施进一步审计程序，审计程序的性质、时间安排和范围应当能够应对评估的舞弊导致的认定层次重大错报风险。例如，针对舞弊导致的认定层次重大错报风险，注册会计师应当考虑实施函证程序以获取更多的相互印证的信息。","seq":30,"links":[{"doc_id":173,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施（2022年12月22日修订）》"}]},{"id":4161,"no":"第三十二条","heading":"","text":"管理层处于实施舞弊的独特地位，其原因是管理层有能力通过凌驾于控制之上操纵会计记录并编制虚假财务报表，而这些控制却看似有效运行。尽管管理层凌驾于控制之上的风险水平因被审计单位而异，但所有被审计单位都存在这种风险。由于管理层凌驾于控制之上的行为发生方式不可预见，这种风险属于舞弊导致的重大错报风险，从而也是一种特别风险。","seq":31},{"id":4162,"no":"第三十三条","heading":"","text":"无论对管理层凌驾于控制之上的风险的评估结果如何，注册会计师都应当设计和实施审计程序，用以： （一）测试日常会计核算过程中作出的会计分录以及编制财务报表过程中作出的其他调整是否适当； （二）复核会计估计是否存在偏向，并评价产生这种偏向的环境是否表明存在舞弊导致的重大错报风险； （三）对于超出被审计单位正常经营过程的重大交易，或基于对被审计单位及其环境的了解以及在审计过程中获取的其他信息而显得异常的重大交易，评价其商业理由（或缺乏商业理由）是否表明被审计单位从事交易的目的是为了对财务信息作出虚假报告或掩盖侵占资产的行为。","seq":32,"links":[{"doc_id":145,"tier":"L3","score":72,"rel_kind":"cites","target_seq":0,"target_art_no":"第1项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》第33条"}]},{"id":4163,"no":"第三十四条","heading":"","text":"在设计和实施审计程序，以测试日常会计核算过程中作出的会计分录以及编制财务报表过程中作出的其他调整是否适当时，注册会计师应当： （一）向参与财务报告过程的人员询问与处理会计分录和其他调整相关的不恰当或异常的活动； **（二）选择在报告期末作出的会计分录和其他调整；** **（三）考虑是否有必要测试整个会计期间的会计分录和其他调整。**","seq":33,"links":[{"doc_id":145,"tier":"L3","score":72,"rel_kind":"cites","target_seq":2,"target_art_no":"第3项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》第34条"}]},{"id":4164,"no":"第三十五条","heading":"","text":"在复核会计估计是否存在偏向时，注册会计师应当： （一）评价管理层在作出会计估计时所作的判断和决策是否反映出管理层的某种偏向（即使判断和决策孤立地看是合理的），从而可能表明存在舞弊导致的重大错报风险。如果存在偏向，注册会计师应当从整体上重新评价会计估计； （二）追溯复核与以前年度财务报表反映的重大会计估计相关的管理层判断和假设。","seq":34},{"id":4165,"no":"第三十六条","heading":"","text":"当按照本准则第三十三条至第三十五条实施的程序无法涵盖特定的管理层凌驾于控制之上的其他风险时，注册会计师还应当确定是否有必要实施其他审计程序，以应对识别出的管理层凌驾于控制之上的风险。 ### 第六节 评价审计证据","seq":35},{"id":4166,"no":"第三十七条","heading":"","text":"在就财务报表与所了解的被审计单位的情况是否一致形成总体结论时，注册会计师应当评价在临近审计结束时实施的分析程序，是否表明存在此前尚未识别的舞弊导致的重大错报风险。","seq":36},{"id":4167,"no":"第三十八条","heading":"","text":"如果识别出某项错报，注册会计师应当评价该项错报是否表明存在舞弊。如果存在舞弊的迹象，鉴于舞弊不太可能是孤立发生的事项，注册会计师应当评价该项错报对审计工作其他方面的影响，特别是对管理层声明可靠性的影响。","seq":37},{"id":4168,"no":"第三十九条","heading":"","text":"如果识别出某项错报，并有理由认为该项错报是或可能是舞弊导致的，且涉及管理层，特别是涉及较高层级的管理层，无论该项错报是否重大，注册会计师都应当重新评价对舞弊导致的重大错报风险的评估结果，以及该结果对旨在应对评估的风险的审计程序的性质、时间安排和范围的影响。在重新考虑此前获取的审计证据的可靠性时，注册会计师还应当考虑相关的情形是否表明可能存在涉及员工、管理层或第三方的串通舞弊。","seq":38},{"id":4169,"no":"第四十条","heading":"","text":"如果确认财务报表存在舞弊导致的重大错报，或无法确定财务报表是否存在舞弊导致的重大错报，注册会计师应当评价这两种情况对审计的影响。 ### 第七节 无法继续执行审计业务","seq":39},{"id":4170,"no":"第四十一条","heading":"","text":"如果舞弊或舞弊嫌疑导致出现错报，致使注册会计师遇到对其继续执行审计业务的能力产生怀疑的异常情形，注册会计师应当： （一）确定适用于具体情况的职业责任和法律责任，包括是否需要向审计业务委托人或监管机构报告； **（二）在相关法律法规允许的情况下，考虑是否需要解除业务约定。**","seq":40},{"id":4171,"no":"第四十二条","heading":"","text":"如果决定解除业务约定，注册会计师应当采取下列措施： （一）与适当层级的管理层和治理层讨论解除业务约定的决定和理由； （二）考虑是否存在职业责任或法律责任，需要向审计业务委托人或监管机构报告解除业务约定的决定和理由。 ### 第八节 书面声明","seq":41},{"id":4172,"no":"第四十三条","heading":"","text":"注册会计师应当就下列事项向管理层和治理层（如适用）获取书面声明： （一）管理层和治理层认可其设计、执行和维护内部控制以防止和发现舞弊的责任； （二）管理层和治理层已向注册会计师披露了管理层对舞弊导致的财务报表重大错报风险的评估结果； （三）管理层和治理层已向注册会计师披露了已知的涉及管理层、在内部控制中承担重要职责的员工以及其他人员（在舞弊行为导致财务报表出现重大错报的情况下）的舞弊或舞弊嫌疑； （四）管理层和治理层已向注册会计师披露了从现任和前任员工、分析师、监管机构等方面获知的、影响财务报表的舞弊指控或舞弊嫌疑。 ### 第九节 与管理层和治理层的沟通","seq":42,"links":[{"doc_id":186,"tier":"L3","score":72,"rel_kind":"cites","target_seq":18,"target_art_no":"第十九条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》第43条"}]},{"id":4173,"no":"第四十四条","heading":"","text":"如果识别出舞弊或获取的信息表明可能存在舞弊，除非法律法规禁止，注册会计师应当及时与适当层级的管理层沟通此类事项，以便管理层告知对防止和发现舞弊事项负有主要责任的人员。","seq":43},{"id":4174,"no":"第四十五条","heading":"","text":"如果确定或怀疑舞弊涉及下列人员，注册会计师应当及时与治理层沟通此类事项，除非治理层全部成员参与管理被审计单位： **（一）管理层；** **（二）在内部控制中承担重要职责的员工；** **（三）其他人员（在舞弊行为导致财务报表重大错报的情况下）。** 如果怀疑舞弊涉及管理层，除非法律法规禁止，注册会计师应当与治理层沟通这一怀疑，并与其讨论为完成审计工作所必需的审计程序的性质、时间安排和范围。","seq":44},{"id":4175,"no":"第四十六条","heading":"","text":"如果根据判断认为还存在与治理层职责相关的、涉及舞弊的其他事项，除非法律法规禁止，注册会计师应当就此与治理层沟通。 ### 第十节 向被审计单位之外的适当机构报告舞弊","seq":45},{"id":4176,"no":"第四十七条","heading":"","text":"如果识别出或怀疑存在舞弊，注册会计师应当确定法律法规或相关职业道德要求是否： **（一）要求注册会计师向被审计单位之外的适当机构作出报告；** （二）规定了相关责任，基于该责任，注册会计师向被审计单位之外的适当机构报告在具体情形下可能是适当的。 ### 第十一节 审计工作底稿","seq":46,"links":[{"doc_id":137,"tier":"L3","score":72,"rel_kind":"cites","target_seq":4,"target_art_no":"第5项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》第47条"}]},{"id":4177,"no":"第四十八条","heading":"","text":"针对《中国注册会计师审计准则第1211号——重大错报风险的识别和评估》所规定的重大错报风险的识别和评估，注册会计师应当将下列内容形成审计工作底稿： （一）项目组内部就舞弊导致财务报表重大错报的可能性进行讨论所得出的重要结论； （二）识别和评估的舞弊导致的财务报表层次和认定层次重大错报风险； （三）在控制活动中识别出的，用于应对评估的舞弊导致的重大错报风险的控制。","seq":47,"links":[{"doc_id":164,"tier":"L3","score":72,"rel_kind":"cites","target_seq":19,"target_art_no":"第二十条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1141号——财务报表审计中与舞弊相关的责任（2022年12月22日修订）》第48条"},{"doc_id":171,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1211号——重大错报风险的识别和评估（2022年12月22日修订）》"}]},{"id":4178,"no":"第四十九条","heading":"","text":"《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施》规定注册会计师应当记录对评估的重大错报风险采取的应对措施。注册会计师应当将下列内容形成审计工作底稿： （一）对评估的舞弊导致的财务报表层次重大错报风险采取的总体应对措施； **（二）审计程序的性质、时间安排和范围；** （三）审计程序与评估的舞弊导致的认定层次重大错报风险之间的联系； （四）实施审计程序（包括用于应对管理层凌驾于控制之上的风险而实施的审计程序）的结果。","seq":48,"links":[{"doc_id":173,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1231号——针对评估的重大错报风险采取的应对措施（2022年12月22日修订）》"}]},{"id":4179,"no":"第五十条","heading":"","text":"注册会计师应当在审计工作底稿中记录与管理层、治理层、监管机构或其他相关各方就舞弊事项进行沟通的情况。","seq":49},{"id":4180,"no":"第五十一条","heading":"","text":"如果认为收入确认存在舞弊风险的假定不适用于业务的具体情况，注册会计师应当在审计工作底稿中记录得出该结论的理由。 ## 第五章 附则","seq":50},{"id":4181,"no":"第五十二条","heading":"","text":"本准则自2023年7月1日起施行。","seq":51}]});
